// ── BARALHO SIBILLA (Sibilla Oracle Cards, 52 cartas) ──
// As imagens são esperadas na pasta sibilla/ (ajuste os nomes abaixo conforme os seus arquivos);
// enquanto o arquivo não existir, o app mostra o ícone 🃏 no lugar.
const SIBILLA_CARDS = {
  'O Amor': {num:'1', oracle:'sim', keywords:["Amor", "Paixão", "Romance"], meaning:'Sentimento verdadeiro e forte, um amor que nasce ou se fortalece. Em qualquer tema, mostra que o coração está no centro da questão.'},
  'O Amigo Sincero': {num:'2', oracle:'sim', keywords:["Amizade", "Lealdade", "Apoio"], meaning:'Alguém de confiança que está ao seu lado e fala a verdade com carinho. Aponta apoio genuíno e conselho honesto.'},
  'A Ausência': {num:'3', oracle:'nao', keywords:["Distância", "Falta", "Separação"], meaning:'Distância física ou emocional; alguém ou algo que faz falta ou ainda não chegou. Pode indicar afastamento temporário ou uma lacuna a ser preenchida.'},
  'A Espera': {num:'4', oracle:'talvez', keywords:["Paciência", "Expectativa", "Tempo"], meaning:'Hora de aguardar: a resposta ainda não veio e forçar não adianta. Pede paciência e confiança no tempo certo das coisas.'},
  'Muito Dinheiro': {num:'5', oracle:'sim', keywords:["Abundância", "Ganho", "Prosperidade"], meaning:'Grande entrada financeira ou fase de fartura. Indica ganho significativo; as cartas vizinhas mostram de onde ele vem.'},
  'O Bilhete Doce': {num:'6', oracle:'sim', keywords:["Declaração", "Carta de amor", "Doçura"], meaning:'Mensagem carinhosa, convite ou declaração; gentileza que chega por palavras. Traz suavidade e romance.'},
  'A Contrariedade': {num:'7', oracle:'nao', keywords:["Aborrecimento", "Desagrado", "Obstáculo"], meaning:'Algo que contraria seus planos e causa irritação ou desgosto. Um aborrecimento que costuma ser passageiro, mas pede jogo de cintura.'},
  'A Infantilidade': {num:'8', oracle:'talvez', keywords:["Imaturidade", "Ingenuidade", "Brincadeira"], meaning:'Atitude imatura ou ingênua, sua ou de alguém próximo; também pode apontar leveza e espontaneidade. Pergunta onde falta maturidade, ou onde sobra rigidez.'},
  'A Tagarelice': {num:'9', oracle:'talvez', keywords:["Fofoca", "Conversa", "Boatos"], meaning:'Muita conversa, comentário e fofoca ao redor. Atenção ao que é dito e a quem escuta: a informação pode circular além do que deveria.'},
  'A Raiva': {num:'10', oracle:'nao', keywords:["Ira", "Explosão", "Conflito"], meaning:'Irritação forte, discussão ou emoção fora de controle. Aconselha respirar antes de agir para não agravar a situação.'},
  'A Esperança': {num:'11', oracle:'sim', keywords:["Otimismo", "Fé", "Desejo"], meaning:'Perspectiva positiva e desejo que ainda pode se realizar. Há luz à frente, mas a esperança precisa vir acompanhada de ação.'},
  'O Inimigo': {num:'12', oracle:'nao', keywords:["Oposição", "Rivalidade", "Cuidado"], meaning:'Alguém ou algo trabalhando contra você, ou uma situação de oposição. Pede atenção redobrada e discrição com seus planos.'},
  'O Impedimento': {num:'13', oracle:'nao', keywords:["Bloqueio", "Entrave", "Obstáculo"], meaning:'Algo se coloca no caminho e trava o andamento. Mostra que é preciso remover o entrave antes de seguir.'},
  'O Bajulador': {num:'14', oracle:'nao', keywords:["Falsidade", "Elogio interesseiro", "Manipulação"], meaning:'Alguém que elogia demais por interesse. Cuidado com palavras doces que escondem segundas intenções.'},
  'A Fidelidade': {num:'15', oracle:'sim', keywords:["Lealdade", "Afeição", "Constância"], meaning:'Lealdade e afeto estáveis; confiança que se confirma. Fala de relações firmes e de pessoas que permanecem.'},
  'O Advogado': {num:'16', oracle:'talvez', keywords:["Justiça", "Orientação", "Processo"], meaning:'Assuntos legais, contratos ou necessidade de orientação especializada. Também pode ser alguém que defende a sua causa.'},
  'A Inconstância': {num:'17', oracle:'nao', keywords:["Instabilidade", "Mudança de ideia", "Volubilidade"], meaning:'Falta de firmeza: sentimentos ou decisões que mudam o tempo todo. Evite apostar em quem, ou no que, não se sustenta.'},
  'Os Jogadores': {num:'18', oracle:'talvez', keywords:["Risco", "Aposta", "Sorte"], meaning:'Risco, jogo e dependência da sorte. Pede cautela com apostas, financeiras ou emocionais, e clareza sobre o que se pode perder.'},
  'O Consulente': {num:'19', oracle:'talvez', keywords:["Figura masculina", "Quem consulta", "Personagem"], meaning:'Representa o homem que consulta, ou um homem central na situação. As cartas ao redor mostram como ele vive o assunto.'},
  'A Consulente': {num:'20', oracle:'talvez', keywords:["Figura feminina", "Quem consulta", "Personagem"], meaning:'Representa a mulher que consulta, ou uma mulher central na situação. As cartas ao redor mostram como ela vive o assunto.'},
  'O Susto': {num:'21', oracle:'nao', keywords:["Medo", "Sobressalto", "Imprevisto"], meaning:'Sobressalto, notícia inesperada ou medo repentino. Costuma ser maior no impacto do que na consequência real.'},
  'A Mulher Zangada': {num:'22', oracle:'nao', keywords:["Irritação", "Mau humor", "Discussão"], meaning:'Uma mulher irritada, ou um clima de mau humor ao redor. Pode ser você; pede diálogo calmo antes que o atrito cresça.'},
  'O Soldado': {num:'23', oracle:'talvez', keywords:["Disciplina", "Proteção", "Coragem"], meaning:'Disciplina, ordem e coragem; alguém que protege ou que age de modo rígido. Também pode indicar um militar ou figura de autoridade.'},
  'A Casa da Cidade': {num:'24', oracle:'sim', keywords:["Lar", "Estabilidade", "Vida urbana"], meaning:'Casa, moradia e vida estruturada na cidade. Fala de segurança, família e assuntos domésticos.'},
  'A Casa de Campo': {num:'25', oracle:'sim', keywords:["Descanso", "Tranquilidade", "Natureza"], meaning:'Sossego, descanso e vida mais simples. Indica a pausa necessária e ambientes tranquilos.'},
  'O Casamento': {num:'26', oracle:'sim', keywords:["União", "Compromisso", "Aliança"], meaning:'Compromisso formal, união ou acordo sério. Vale para casamento, mas também para sociedades e parcerias.'},
  'A Fraqueza': {num:'27', oracle:'nao', keywords:["Vulnerabilidade", "Cansaço", "Desânimo"], meaning:'Momento de fragilidade, física ou emocional. Pede cuidado, descanso e apoio, sem se cobrar além da conta.'},
  'O Pensamento': {num:'28', oracle:'talvez', keywords:["Reflexão", "Mente", "Lembrança"], meaning:'Alguém está pensando no assunto (ou em você), ou é hora de refletir antes de agir. Ruminar demais também pode paralisar.'},
  'Os Presentes': {num:'29', oracle:'sim', keywords:["Presente", "Gentileza", "Recompensa"], meaning:'Presente, agrado ou ajuda que chega. Gestos de generosidade e recompensa por esforços anteriores.'},
  'A Perda de Dinheiro': {num:'30', oracle:'nao', keywords:["Prejuízo", "Gasto", "Descuido"], meaning:'Gasto inesperado, prejuízo ou desperdício. Pede atenção às finanças e às decisões impulsivas.'},
  'O Protetor': {num:'31', oracle:'sim', keywords:["Proteção", "Amparo", "Influência"], meaning:'Alguém com mais poder ou influência que ampara você; também a sensação de estar protegida. Boa carta para pedir ajuda.'},
  'A Armadilha': {num:'32', oracle:'nao', keywords:["Cilada", "Engano", "Perigo oculto"], meaning:'Cilada ou situação com algo escondido. Examine promessas boas demais e leia tudo antes de assinar ou aceitar.'},
  'A Viagem ao Campo': {num:'33', oracle:'sim', keywords:["Passeio", "Leveza", "Descanso"], meaning:'Passeio, escapada ou momento de lazer fora da rotina. Traz alívio, renovação e a chance de espairecer.'},
  'O Passatempo': {num:'34', oracle:'sim', keywords:["Prazer", "Diversão", "Lazer"], meaning:'Momentos agradáveis, diversão e prazer. Convite a cuidar da própria alegria.'},
  'A Briga': {num:'35', oracle:'nao', keywords:["Discussão", "Desavença", "Atrito"], meaning:'Desentendimento, rixa ou atrito aberto. Observe o que está por trás da discussão antes de reagir.'},
  'O Atraso': {num:'36', oracle:'nao', keywords:["Demora", "Adiamento", "Lentidão"], meaning:'As coisas demoram mais do que o esperado: adiamentos e burocracia. Nem sempre é ruim, às vezes o atraso protege.'},
  'O Aposentado': {num:'37', oracle:'talvez', keywords:["Experiência", "Descanso", "Idade"], meaning:'Pessoa mais velha, experiência acumulada ou fase de desacelerar. Pode indicar sabedoria, ou estagnação.'},
  'A Reconciliação': {num:'38', oracle:'sim', keywords:["Paz", "Reencontro", "Perdão"], meaning:'Fazer as pazes, retomar contato, superar uma mágoa. Indica reaproximação possível se houver abertura dos dois lados.'},
  'A Revelação Importante': {num:'39', oracle:'talvez', keywords:["Verdade", "Descoberta", "Segredo revelado"], meaning:'Algo importante vem à tona. A carta ao lado diz se a descoberta alivia ou pesa.'},
  'O Sucesso': {num:'40', oracle:'sim', keywords:["Êxito", "Reconhecimento", "Conquista"], meaning:'Resultado favorável, conquista e reconhecimento. Esforço que dá frutos.'},
  'A Surpresa': {num:'41', oracle:'talvez', keywords:["Imprevisto", "Novidade", "Inesperado"], meaning:'Algo inesperado, bom ou ruim conforme as vizinhas. Prepare-se para sair do roteiro.'},
  'A Ternura': {num:'42', oracle:'sim', keywords:["Carinho", "Delicadeza", "Afeto"], meaning:'Afeto suave, carinho e cuidado entre pessoas. Um toque de delicadeza que acalma e cura.'},
  'A Mulher Loira': {num:'43', oracle:'talvez', keywords:["Figura feminina", "Cabelos claros", "Terceira pessoa"], meaning:'Mulher de cabelos claros, ou uma figura feminina importante na história. O tom da leitura vem das cartas vizinhas.'},
  'A Viúva': {num:'44', oracle:'talvez', keywords:["Solidão", "Luto", "Independência"], meaning:'Solidão, perda ou fase de recomeçar sozinha. Também aponta independência e uma mulher que seguiu em frente.'},
  'Algum Dinheiro': {num:'45', oracle:'sim', keywords:["Ganho modesto", "Sustento", "Entrada"], meaning:'Um dinheiro que chega, sem ser fortuna. Garante o necessário e alivia o orçamento.'},
  'A Carta': {num:'46', oracle:'talvez', keywords:["Mensagem", "Notícia", "Documento"], meaning:'Mensagem, notícia ou documento a caminho. Quem envia e o tom dependem das cartas vizinhas.'},
  'O Jovem Moreno': {num:'47', oracle:'talvez', keywords:["Figura masculina", "Jovem", "Cabelos escuros"], meaning:'Rapaz de cabelos escuros, ou um jovem importante na situação. Costuma aparecer em temas de amor e novidade.'},
  'A Mulher Morena': {num:'48', oracle:'talvez', keywords:["Figura feminina", "Cabelos escuros", "Terceira pessoa"], meaning:'Mulher de cabelos escuros, ou uma figura feminina marcante. Observe as cartas ao lado para entender o papel dela.'},
  'O Ladrão': {num:'49', oracle:'nao', keywords:["Roubo", "Perda", "Traição"], meaning:'Perda causada por terceiros: roubo, golpe ou alguém que tira algo seu. Pede proteção de bens, tempo e confiança.'},
  'A Viagem': {num:'50', oracle:'sim', keywords:["Deslocamento", "Mudança", "Caminho"], meaning:'Deslocamento, viagem ou mudança de fase. Movimento rumo a novas paisagens.'},
  'A Visita': {num:'51', oracle:'talvez', keywords:["Chegada", "Encontro", "Novidade"], meaning:'Alguém chega, ou você vai ao encontro de alguém. A visita pode trazer alegria ou obrigação, conforme as vizinhas.'},
  'A Vitória': {num:'52', oracle:'sim', keywords:["Triunfo", "Superação", "Resultado"], meaning:'Superação e triunfo sobre uma dificuldade. A carta de fechamento: esforço recompensado.'},
};

